//! Persistent topological names, v0 (`docs/research/tecnologia-rust-cad.md` §6).
//!
//! A face is referenced by how it was born, not by a kernel index:
//! `F1:+Z` is the +Z face of the box created by feature F1, `F3:g2` the third
//! face generated by F3, `F1:+Z/1` the second piece of `F1:+Z` after a split.
//! The engine propagates names through every operation's `OpHistory`; Phase 1
//! adds semantic queries and scored fallback on top of this.
//!
//! An edge is named by the two faces that meet at it (ADR-0004): `F1:+X|F1:+Z`,
//! with the face names sorted so the same edge always gets the same text.

use crate::FeatureId;
use serde::{Deserialize, Deserializer, Serialize, Serializer};
use std::fmt;
use std::str::FromStr;

/// Name of a face that survives rebuilds.
#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub enum TopoName {
    /// A face of a primitive, by role (e.g. `+Z` for a box's top face).
    Primitive {
        /// Feature that created the primitive.
        feature: FeatureId,
        /// Role inside the primitive: `+X -X +Y -Y +Z -Z` for boxes.
        role: String,
    },
    /// A face an operation created that has no single parent, numbered by a
    /// deterministic geometric order.
    Generated {
        /// The feature that created it.
        feature: FeatureId,
        /// Ordinal among the faces that feature generated.
        ordinal: u32,
    },
    /// A piece of a face that was split.
    Split {
        /// The face that was split.
        parent: Box<TopoName>,
        /// Ordinal among the pieces.
        ordinal: u32,
    },
}

/// Error parsing a [`TopoName`].
#[derive(Clone, Debug, PartialEq, Eq, thiserror::Error)]
#[error("invalid face name `{0}` (expected e.g. `F1:+Z`, `F3:g2`, `F1:+Z/1`)")]
pub struct NameParseError(pub String);

impl fmt::Display for TopoName {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            TopoName::Primitive { feature, role } => write!(f, "{feature}:{role}"),
            TopoName::Generated { feature, ordinal } => write!(f, "{feature}:g{ordinal}"),
            TopoName::Split { parent, ordinal } => write!(f, "{parent}/{ordinal}"),
        }
    }
}

/// Longest accepted name, to bound parsing work on hostile input.
const MAX_NAME_LEN: usize = 256;

impl FromStr for TopoName {
    type Err = NameParseError;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        let err = || NameParseError(s.chars().take(64).collect());
        if s.len() > MAX_NAME_LEN {
            return Err(err());
        }
        if let Some((parent, ord)) = s.rsplit_once('/') {
            let ordinal = ord.parse().map_err(|_| err())?;
            return Ok(TopoName::Split {
                parent: Box::new(parent.parse()?),
                ordinal,
            });
        }
        let (feature, role) = s.split_once(':').ok_or_else(err)?;
        let feature: FeatureId = feature.parse().map_err(|_| err())?;
        if let Some(Ok(ordinal)) = role.strip_prefix('g').map(str::parse) {
            return Ok(TopoName::Generated { feature, ordinal });
        }
        let valid_role = !role.is_empty()
            && role
                .chars()
                .all(|c| c.is_ascii_alphanumeric() || matches!(c, '+' | '-' | '_' | '.'));
        if !valid_role {
            return Err(err());
        }
        Ok(TopoName::Primitive {
            feature,
            role: role.to_owned(),
        })
    }
}

/// Name of a B-rep edge that survives rebuilds: its two adjacent faces, sorted
/// by [`TopoName`]'s order (feature number, then primitive roles before
/// generated faces before split pieces).
///
/// A seam (an edge a face meets itself at) has the same name twice. Two faces
/// that meet at more than one edge give an ambiguous name; v0 leaves those
/// edges unnamed (ADR-0004).
#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct EdgeName {
    a: TopoName,
    b: TopoName,
}

impl EdgeName {
    /// The name of the edge between two faces, in either order.
    pub fn new(x: TopoName, y: TopoName) -> Self {
        if x <= y {
            Self { a: x, b: y }
        } else {
            Self { a: y, b: x }
        }
    }

    /// The two face names, smallest first.
    pub fn faces(&self) -> [&TopoName; 2] {
        [&self.a, &self.b]
    }
}

/// Error parsing an [`EdgeName`].
#[derive(Clone, Debug, PartialEq, Eq, thiserror::Error)]
#[error("invalid edge name `{0}` (expected two face names joined by `|`, e.g. `F1:+X|F1:+Z`)")]
pub struct EdgeNameParseError(pub String);

impl fmt::Display for EdgeName {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}|{}", self.a, self.b)
    }
}

impl FromStr for EdgeName {
    type Err = EdgeNameParseError;

    /// Accepts the faces in either order; displays them sorted.
    fn from_str(s: &str) -> Result<Self, Self::Err> {
        let err = || EdgeNameParseError(s.chars().take(64).collect());
        if s.len() > 2 * MAX_NAME_LEN + 1 {
            return Err(err());
        }
        let (x, y) = s.split_once('|').ok_or_else(err)?;
        let x: TopoName = x.parse().map_err(|_| err())?;
        let y: TopoName = y.parse().map_err(|_| err())?;
        Ok(Self::new(x, y))
    }
}

impl Serialize for EdgeName {
    fn serialize<S: Serializer>(&self, s: S) -> Result<S::Ok, S::Error> {
        s.collect_str(self)
    }
}

impl<'de> Deserialize<'de> for EdgeName {
    fn deserialize<D: Deserializer<'de>>(d: D) -> Result<Self, D::Error> {
        let s = String::deserialize(d)?;
        s.parse().map_err(serde::de::Error::custom)
    }
}

impl Serialize for TopoName {
    fn serialize<S: Serializer>(&self, s: S) -> Result<S::Ok, S::Error> {
        s.collect_str(self)
    }
}

impl<'de> Deserialize<'de> for TopoName {
    fn deserialize<D: Deserializer<'de>>(d: D) -> Result<Self, D::Error> {
        let s = String::deserialize(d)?;
        s.parse().map_err(serde::de::Error::custom)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use proptest::prelude::*;

    #[test]
    fn round_trips() {
        for s in ["F1:+Z", "F12:-X", "F3:g0", "F3:g12", "F1:+Z/1", "F2:g1/0/3"] {
            let n: TopoName = s.parse().unwrap();
            assert_eq!(n.to_string(), s);
            let json = serde_json::to_string(&n).unwrap();
            assert_eq!(serde_json::from_str::<TopoName>(&json).unwrap(), n);
        }
    }

    #[test]
    fn rejects_garbage() {
        for s in [
            "", "F1", ":+Z", "X1:+Z", "F1:", "F1:+Z/x", "F1:a b", "F-1:+Z",
        ] {
            assert!(s.parse::<TopoName>().is_err(), "{s}");
        }
    }

    #[test]
    fn edge_names_are_sorted_and_round_trip() {
        let n: EdgeName = "F1:+Z|F1:+X".parse().unwrap();
        assert_eq!(n.to_string(), "F1:+X|F1:+Z");
        assert_eq!(n, "F1:+X|F1:+Z".parse().unwrap());
        let [a, b] = n.faces();
        assert_eq!(
            (a.to_string(), b.to_string()),
            ("F1:+X".into(), "F1:+Z".into())
        );
        for s in [
            "F1:+X|F1:+Z",
            "F2:g0|F2:g0",
            "F3:g2|F1:+Z/1",
            "F2:+X|F10:+X",
        ] {
            let n: EdgeName = s.parse().unwrap();
            assert_eq!(n.to_string(), s);
            let json = serde_json::to_string(&n).unwrap();
            assert_eq!(serde_json::from_str::<EdgeName>(&json).unwrap(), n);
        }
    }

    #[test]
    fn edge_names_reject_garbage() {
        for s in [
            "",
            "|",
            "F1:+X",
            "F1:+X|",
            "|F1:+X",
            "F1:+X|F1:+Y|F1:+Z",
            "F1:+X||F1:+Z",
            "F1:+X|X1:+Z",
        ] {
            assert!(s.parse::<EdgeName>().is_err(), "{s}");
        }
        assert!(serde_json::from_str::<EdgeName>("\"F1:+X\"").is_err());
    }

    proptest! {
        #[test]
        fn never_panics(s in ".{0,300}") {
            let _ = s.parse::<TopoName>();
            let _ = s.parse::<EdgeName>();
        }

        #[test]
        fn edge_name_order_does_not_matter(a in 1u32..50, b in 1u32..50, ra in 0u32..4, rb in 0u32..4) {
            let x = TopoName::Generated { feature: FeatureId(a), ordinal: ra };
            let y = TopoName::Generated { feature: FeatureId(b), ordinal: rb };
            let n = EdgeName::new(x.clone(), y.clone());
            prop_assert_eq!(&n, &EdgeName::new(y, x));
            prop_assert_eq!(n.to_string().parse::<EdgeName>().unwrap(), n);
        }
    }
}
